// throwaway validation prototype for the SPEC (not the deliverable)
const NIL: usize = usize::MAX;

#[derive(Clone)]
struct Node { i: u32, x: f64, y: f64, prev: usize, next: usize, z: i32, prevz: usize, nextz: usize, steiner: bool }

struct E { a: Vec<Node>, idx: Vec<u32>, verts: usize, hashing: bool, minx: f64, miny: f64, maxx: f64, maxy: f64, inv: f64 }

impl E {
    fn new() -> E { E{a:Vec::new(), idx:Vec::new(), verts:0, hashing:false, minx:0.,miny:0.,maxx:0.,maxy:0., inv:0.} }
    fn x(&self,p:usize)->f64{self.a[p].x}
    fn y(&self,p:usize)->f64{self.a[p].y}
    fn pv(&self,p:usize)->usize{self.a[p].prev}
    fn nx(&self,p:usize)->usize{self.a[p].next}
    fn area(&self,p:usize,q:usize,r:usize)->f64{
        (self.y(q)-self.y(p))*(self.x(r)-self.x(q)) - (self.x(q)-self.x(p))*(self.y(r)-self.y(q))
    }
    fn equals(&self,p:usize,q:usize)->bool{ self.x(p)==self.x(q) && self.y(p)==self.y(q) }
    fn insert_node(&mut self, i: usize, px: f64, py: f64, last: usize) -> usize {
        let p = self.a.len();
        self.a.push(Node{i:i as u32,x:px,y:py,prev:NIL,next:NIL,z:0,prevz:NIL,nextz:NIL,steiner:false});
        if last == NIL { self.a[p].prev = p; self.a[p].next = p; }
        else {
            let ln = self.a[last].next;
            self.a[p].next = ln; self.a[p].prev = last;
            self.a[ln].prev = p; self.a[last].next = p;
        }
        p
    }
    fn remove_node(&mut self, p: usize) {
        let (pp, pn) = (self.a[p].prev, self.a[p].next);
        self.a[pn].prev = pp; self.a[pp].next = pn;
        let (pz, nz) = (self.a[p].prevz, self.a[p].nextz);
        if pz != NIL { self.a[pz].nextz = nz; }
        if nz != NIL { self.a[nz].prevz = pz; }
    }
    fn linked_list(&mut self, pts: &[[f64;2]], clockwise: bool) -> usize {
        let mut sum = 0.0f64;
        let len = pts.len();
        let mut last = NIL;
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = pts[i]; let p2 = pts[j];
            sum += (p2[0]-p1[0])*(p1[1]+p2[1]);
            j = i;
        }
        if clockwise == (sum > 0.0) {
            for i in 0..len { last = self.insert_node(self.verts+i, pts[i][0], pts[i][1], last); }
        } else {
            for i in (0..len).rev() { last = self.insert_node(self.verts+i, pts[i][0], pts[i][1], last); }
        }
        if last != NIL {
            let ln = self.a[last].next;
            if self.equals(last, ln) { self.remove_node(last); last = ln; }
        }
        self.verts += len;
        last
    }
    fn filter_points(&mut self, start: usize, end0: usize) -> usize {
        if start == NIL { return NIL; }
        let mut end = if end0 == NIL { start } else { end0 };
        let mut p = start;
        loop {
            let mut again = false;
            let pn = self.a[p].next; let pp = self.a[p].prev;
            if !self.a[p].steiner && (self.equals(p,pn) || self.area(pp,p,pn)==0.0) {
                self.remove_node(p);
                p = self.a[p].prev; end = p;
                if p == self.a[p].next { break; }
                again = true;
            } else { p = self.a[p].next; }
            if !(again || p != end) { break; }
        }
        end
    }
    fn point_in_triangle(&self, ax:f64,ay:f64,bx:f64,by:f64,cx:f64,cy:f64,px:f64,py:f64)->bool{
        (cx-px)*(ay-py)-(ax-px)*(cy-py) >= 0.0 &&
        (ax-px)*(by-py)-(bx-px)*(ay-py) >= 0.0 &&
        (bx-px)*(cy-py)-(cx-px)*(by-py) >= 0.0
    }
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.pv(ear); let b = ear; let c = self.nx(ear);
        if self.area(a,b,c) >= 0.0 { return false; }
        let (ax,ay,bx,by,cx,cy)=(self.x(a),self.y(a),self.x(b),self.y(b),self.x(c),self.y(c));
        let mut p = self.nx(self.nx(ear));
        while p != self.pv(ear) {
            if self.point_in_triangle(ax,ay,bx,by,cx,cy,self.x(p),self.y(p))
               && self.area(self.pv(p),p,self.nx(p)) >= 0.0 { return false; }
            p = self.nx(p);
        }
        true
    }
    fn z_order(&self, xf: f64, yf: f64) -> i32 {
        let mut x = ((xf - self.minx) * self.inv) as i32;
        let mut y = ((yf - self.miny) * self.inv) as i32;
        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;
        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;
        x | (y << 1)
    }
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.pv(ear); let b = ear; let c = self.nx(ear);
        if self.area(a,b,c) >= 0.0 { return false; }
        let (ax,ay,bx,by,cx,cy)=(self.x(a),self.y(a),self.x(b),self.y(b),self.x(c),self.y(c));
        let mintx = ax.min(bx.min(cx)); let minty = ay.min(by.min(cy));
        let maxtx = ax.max(bx.max(cx)); let maxty = ay.max(by.max(cy));
        let minz = self.z_order(mintx, minty); let maxz = self.z_order(maxtx, maxty);
        let mut p = self.a[ear].prevz; let mut n = self.a[ear].nextz;
        while p != NIL && self.a[p].z >= minz && n != NIL && self.a[n].z <= maxz {
            if p != a && p != c && self.point_in_triangle(ax,ay,bx,by,cx,cy,self.x(p),self.y(p))
               && self.area(self.pv(p),p,self.nx(p)) >= 0.0 { return false; }
            p = self.a[p].prevz;
            if n != a && n != c && self.point_in_triangle(ax,ay,bx,by,cx,cy,self.x(n),self.y(n))
               && self.area(self.pv(n),n,self.nx(n)) >= 0.0 { return false; }
            n = self.a[n].nextz;
        }
        while p != NIL && self.a[p].z >= minz {
            if p != a && p != c && self.point_in_triangle(ax,ay,bx,by,cx,cy,self.x(p),self.y(p))
               && self.area(self.pv(p),p,self.nx(p)) >= 0.0 { return false; }
            p = self.a[p].prevz;
        }
        while n != NIL && self.a[n].z <= maxz {
            if n != a && n != c && self.point_in_triangle(ax,ay,bx,by,cx,cy,self.x(n),self.y(n))
               && self.area(self.pv(n),n,self.nx(n)) >= 0.0 { return false; }
            n = self.a[n].nextz;
        }
        true
    }
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.a[p].z == 0 { let (px,py)=(self.x(p),self.y(p)); self.a[p].z = self.z_order(px,py); }
            self.a[p].prevz = self.a[p].prev;
            self.a[p].nextz = self.a[p].next;
            p = self.a[p].next;
            if p == start { break; }
        }
        let pz = self.a[p].prevz;
        self.a[pz].nextz = NIL;
        self.a[p].prevz = NIL;
        self.sort_linked(p);
    }
    fn sort_linked(&mut self, list0: usize) -> usize {
        let mut list = list0;
        let mut in_size = 1i32;
        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;
            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0i32;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.a[q].nextz;
                    if q == NIL { break; }
                }
                let mut q_size = in_size;
                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 { e = q; q = self.a[q].nextz; q_size -= 1; }
                    else if q_size == 0 || q == NIL { e = p; p = self.a[p].nextz; p_size -= 1; }
                    else if self.a[p].z <= self.a[q].z { e = p; p = self.a[p].nextz; p_size -= 1; }
                    else { e = q; q = self.a[q].nextz; q_size -= 1; }
                    if tail != NIL { self.a[tail].nextz = e; } else { list = e; }
                    self.a[e].prevz = tail;
                    tail = e;
                }
                p = q;
            }
            self.a[tail].nextz = NIL;
            if num_merges <= 1 { return list; }
            in_size *= 2;
        }
    }
    fn earcut_linked(&mut self, ear0: usize, pass: i32) {
        if ear0 == NIL { return; }
        let mut ear = ear0;
        if pass == 0 && self.hashing { self.index_curve(ear); }
        let mut stop = ear;
        while self.a[ear].prev != self.a[ear].next {
            let prev = self.a[ear].prev; let next = self.a[ear].next;
            let ok = if self.hashing { self.is_ear_hashed(ear) } else { self.is_ear(ear) };
            if ok {
                self.idx.push(self.a[prev].i);
                self.idx.push(self.a[ear].i);
                self.idx.push(self.a[next].i);
                self.remove_node(ear);
                ear = self.a[next].next;
                stop = ear;
                continue;
            }
            ear = next;
            if ear == stop {
                eprintln!("FALLBACK pass={}", pass);
                if pass == 0 { let f = self.filter_points(ear, NIL); self.earcut_linked(f, 1); }
                else if pass == 1 { /* omitted in proto */ }
                break;
            }
        }
    }
    fn run(&mut self, polygon: &Vec<Vec<[f64;2]>>) {
        self.idx.clear(); self.verts = 0;
        if polygon.is_empty() { return; }
        let mut threshold: i32 = 80;
        let mut len: usize = 0;
        let mut i = 0;
        while threshold >= 0 && i < polygon.len() {
            threshold -= polygon[i].len() as i32;
            len += polygon[i].len();
            i += 1;
        }
        let _ = len;
        let outer = self.linked_list(&polygon[0].clone(), true);
        if outer == NIL || self.a[outer].prev == self.a[outer].next { return; }
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.a[outer].next;
            self.minx = self.x(outer); self.maxx = self.minx;
            self.miny = self.y(outer); self.maxy = self.miny;
            loop {
                let (x,y)=(self.x(p),self.y(p));
                if x < self.minx { self.minx = x; }
                if y < self.miny { self.miny = y; }
                if x > self.maxx { self.maxx = x; }
                if y > self.maxy { self.maxy = y; }
                p = self.a[p].next;
                if p == outer { break; }
            }
            let mut s = (self.maxx-self.minx).max(self.maxy-self.miny);
            s = if s != 0.0 { 32767.0 / s } else { 0.0 };
            self.inv = s;
        }
        self.earcut_linked(outer, 0);
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let n: i32 = if args.len() > 1 { args[1].trim().parse::<i32>().unwrap_or(0) } else { 1 };
    let m = n.wrapping_mul(3);
    let mut ring: Vec<[f64;2]> = Vec::new();
    let mut i = 0i32;
    while i < m {
        let angle = 2.0 * std::f64::consts::PI * (i as f64) / (m as f64);
        ring.push([angle.cos(), angle.sin()]);
        i += 1;
    }
    let polygon = vec![ring];
    let mut e = E::new();
    e.run(&polygon);
    let mut out = String::new();
    for v in &e.idx { out.push_str(&v.to_string()); out.push(' '); }
    print!("{}", out);
}
